// ==UserScript==
// @name         VenueRank Lens
// @namespace    https://github.com/qirunzeng/VenueRank-Lens
// @version      1.2.0
// @description  Show CCF 2026, ICORE 2026, and TH-CPL 2019 venue ranks on supported publication sites.
// @author       Qirun Zeng
// @license      MIT
// @match        https://scholar.google.com/*
// @match        https://dl.acm.org/*
// @match        https://ieeexplore.ieee.org/*
// @match        https://dblp.org/*
// @match        https://dblp.uni-trier.de/*
// @homepageURL  https://github.com/qirunzeng/VenueRank-Lens
// @supportURL   https://github.com/qirunzeng/VenueRank-Lens/issues
// @downloadURL  https://raw.githubusercontent.com/qirunzeng/VenueRank-Lens/main/dist/ccf-lens.user.js
// @updateURL    https://raw.githubusercontent.com/qirunzeng/VenueRank-Lens/main/dist/ccf-lens.user.js
// @run-at       document-idle
// @noframes
// @grant        GM_registerMenuCommand
// ==/UserScript==
(() => {
  const style = document.createElement("style");
  style.textContent = ".ccf-lens-badge {\n  --ccf-lens-color: #64748b;\n  display: inline-flex;\n  align-items: center;\n  min-height: 1.5em;\n  margin-inline: 0.45em;\n  padding: 0.08em 0.55em;\n  border: 1px solid color-mix(in srgb, var(--ccf-lens-color), white 24%);\n  border-radius: 999px;\n  background: color-mix(in srgb, var(--ccf-lens-color), transparent 86%);\n  color: var(--ccf-lens-color);\n  font: 700 0.78rem/1.35 -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n  letter-spacing: 0.01em;\n  vertical-align: 0.08em;\n  white-space: nowrap;\n}\n\n.ccf-lens-ccf-rank-a { --ccf-lens-color: #b42318; }\n.ccf-lens-ccf-rank-b { --ccf-lens-color: #b54708; }\n.ccf-lens-ccf-rank-c { --ccf-lens-color: #027a48; }\n\n.ccf-lens-core-rank-a-star { --ccf-lens-color: #6938ef; }\n.ccf-lens-core-rank-a { --ccf-lens-color: #175cd3; }\n.ccf-lens-core-rank-b,\n.ccf-lens-core-rank-au-b { --ccf-lens-color: #087e8b; }\n.ccf-lens-core-rank-c,\n.ccf-lens-core-rank-au-c { --ccf-lens-color: #475467; }\n\n.ccf-lens-th-rank-a { --ccf-lens-color: #7a271a; }\n.ccf-lens-th-rank-b { --ccf-lens-color: #9e165f; }\n\n@media (prefers-color-scheme: dark) {\n  .ccf-lens-ccf-rank-a { --ccf-lens-color: #f97066; }\n  .ccf-lens-ccf-rank-b { --ccf-lens-color: #fdb022; }\n  .ccf-lens-ccf-rank-c { --ccf-lens-color: #32d583; }\n  .ccf-lens-core-rank-a-star { --ccf-lens-color: #b692f6; }\n  .ccf-lens-core-rank-a { --ccf-lens-color: #84adff; }\n  .ccf-lens-core-rank-b,\n  .ccf-lens-core-rank-au-b { --ccf-lens-color: #5fe9d0; }\n  .ccf-lens-core-rank-c,\n  .ccf-lens-core-rank-au-c { --ccf-lens-color: #d0d5dd; }\n  .ccf-lens-th-rank-a { --ccf-lens-color: #fda29b; }\n  .ccf-lens-th-rank-b { --ccf-lens-color: #f9a8d4; }\n}\n";
  (document.head || document.documentElement).append(style);
})();
GM_registerMenuCommand("★ VenueRank Lens by Qirun Zeng — GitHub", () => {
  window.open("https://github.com/qirunzeng/VenueRank-Lens", "_blank", "noopener,noreferrer");
});
